242	// loadDir 扫描目录中的全部作业记录并重建内存索引。
243	//
244	// 恢复规则：
245	//   - 上次关闭时仍为 running 的作业标记为失败，原因是计算被中断；
246	//   - 成功记录缺少归档、校验值对不上，实际输入与原始参数或直接依赖数量
247	//     不对应，或归档数值结果与有效输入按计算规则应得的结果不符时，
248	//     fail-closed 地标记为失败，维持“成功必有完整归档”的不变量。
249	func loadDir(dir string) ([]*storedJob, uint64, error) {
250		entries, err := os.ReadDir(dir)
251		if err != nil {
252			return nil, 0, err
253		}
254		var jobs []*storedJob
255		var maxID uint64
256		for _, e := range entries {
257			name := e.Name()
258			if e.IsDir() {
259				continue
260			}
261			// 清理上一进程崩溃时可能残留的原子写临时文件。
262			if strings.HasPrefix(name, ".tmp-") {
263				_ = os.Remove(filepath.Join(dir, name))
264				continue
265			}
266			if !strings.HasPrefix(name, "job-") || !strings.HasSuffix(name, ".json") {
267				continue
268			}
269			path := filepath.Join(dir, name)
270			data, err := os.ReadFile(path)
271			if err != nil {
272				return nil, 0, err
273			}
274			var r jobRecord
275			if err := json.Unmarshal(data, &r); err != nil {
276				return nil, 0, fmt.Errorf("numeric: 记录 %s 损坏: %w", name, err)
277			}
278			if r.Version != recordVersion {
279				return nil, 0, fmt.Errorf("numeric: 记录 %s 版本不受支持: %s", name, r.Version)
280			}
281			// 提交人、请求号按完整字节恢复：含非法 UTF-8 字节时以
282			// identity_raw 兜底字段为准，普通文本（含 U+0000）与旧归档原样使用。
283			submitter, requestID, err := resolveIdentity(r.Submitter, r.RequestID, r.IdentityRaw)
284			if err != nil {
285				return nil, 0, fmt.Errorf("numeric: 记录 %s 标识损坏: %w", name, err)
286			}
287			// 成功归档内嵌同一份标识，同样按其自身兜底字段恢复，保证顶层记录
288			// 与归档中的参数逐字节一致。
289			if r.Archive != nil {
290				aSub, aReq, aErr := resolveIdentity(r.Archive.Submitter, r.Archive.RequestID, r.Archive.IdentityRaw)
291				if aErr != nil {
292					return nil, 0, fmt.Errorf("numeric: 记录 %s 归档标识损坏: %w", name, aErr)
293				}
294				r.Archive.Submitter = aSub
295				r.Archive.RequestID = aReq
296			}
297			switch r.Status {
298			case StatusQueued, StatusRunning, StatusSucceeded, StatusFailed, StatusCanceled:
299			default:
300				return nil, 0, fmt.Errorf("numeric: 记录 %s 状态非法: %q", name, r.Status)
301			}
302			// 新格式记录直接给出有序依赖列表；旧格式记录只有单依赖字段，
303			// 恢复为只含一个作业号的列表（语义与提交时一致）。
304			deps := append([]uint64(nil), r.Dependencies...)
305			if len(deps) == 0 && r.HasDependency {
306				deps = []uint64{r.DependencyID}
307			}
308			j := &storedJob{
309				id:           r.ID,
310				submitter:    submitter,
311				requestID:    requestID,
312				seed:         r.Seed,
313				values:       append([]int64(nil), r.Values...),
314				dependencies: deps,
315	
316				queuedAt:   r.QueuedAt,
317				startedAt:  r.StartedAt,
318				finishedAt: r.FinishedAt,
319	
320				status:        r.Status,
321				failureReason: r.FailureReason,
322				blockerID:     r.BlockerID,
323	
324				effectiveValues: append([]int64(nil), r.EffectiveValues...),
325				archive:         r.Archive,
326			}
327			if j.status == StatusRunning {
328				j.status = StatusFailed
329				j.failureReason = "计算被中断：归档上次关闭时作业仍在运行"
330				j.blockerID = 0
331				if j.finishedAt.IsZero() {
332					j.finishedAt = time.Now().UTC()
333				}
334				j.effectiveValues = nil
335				j.archive = nil
336				// 就地重写恢复后的终态。
337				if data, err := encodeRecord(j); err == nil {
338					_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
339				}
340			}
341			if j.status == StatusSucceeded {
342				// 除完整性外，还必须满足两条独立的对应/复算规则：
343				//  1. 实际输入与原始参数、直接依赖数量逐项对应——原始序列非空且
344				//     按原次序完整出现在实际输入开头，总长度恰为原始长度加上直接
345				//     依赖数；摘要、日志、校验值只与“实际输入”绑定，换成另一份
346				//     序列（如 [-3,2] 冒充 [2,-3]）仍能全套自洽，只有按位置比对
347				//     原始参数与依赖数量才能识别。
348				//  2. 归档中的数值结果必须与实际输入按既有计算规则应得的结果一致：
349				//     日志、摘要与校验值都可能与错误数字自洽，只有按保存的实际
350				//     输入复算才能识别。
351				// 任一不符合都按损坏归档处理。
352				var invalidReason string
353				switch {
354				case !archiveIntact(j):
355					invalidReason = "归档不完整或校验值不一致，成功结果不可用"
356				case !effectiveInputsCorrespond(j):
357					invalidReason = "实际输入与原始参数或依赖数量不符，成功结果不可用"
358				case !archiveResultsValid(j):
359					invalidReason = "归档数值结果与有效输入按计算规则应得的结果不符，成功结果不可用"
360				}
361				if invalidReason != "" {
362					j.status = StatusFailed
363					j.failureReason = invalidReason
364					if j.finishedAt.IsZero() {
365						j.finishedAt = time.Now().UTC()
366					}
367					j.effectiveValues = nil
368					j.archive = nil
369					if data, err := encodeRecord(j); err == nil {
370						_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
371					}
372				}
373			}
374			jobs = append(jobs, j)
375			if j.id > maxID {
376				maxID = j.id
377			}
378		}
379		// 恢复后的排列必须与关闭前的接受先后一致：作业号在接受时单调分配，
380		// 按作业号升序即提交先后。记录上的提交时间只用于时间范围过滤，
381		// 不参与排序——本机时钟回拨会让后接受的作业带有更早的时间，
382		// 按时间重排会改变已确定的先后关系（也会让上游作业号更大的
383		// 依赖链在单趟级联扫描中漏掉失败传播）。
384		sort.Slice(jobs, func(a, b int) bool {
385			return jobs[a].id < jobs[b].id
386		})
387		return jobs, maxID, nil
388	}
389	
390	// archiveIntact 复算成功归档的全部确定性字段，任何不一致都视为不可用。
391	func archiveIntact(j *storedJob) bool {
392		a := j.archive
393		if a == nil {
394			return false
395		}
396		// 归档中的原始参数必须与记录顶层字段一致。
397		if a.JobID != j.id || a.Submitter != j.submitter || a.RequestID != j.requestID ||
398			a.Seed != j.seed || a.HasDependency != (len(j.dependencies) > 0) {
399			return false
400		}
401		if a.HasDependency && a.DependencyID != depID(j) {
402			return false
403		}
404		// 依赖列表（内容与次序）必须一致。旧格式归档没有 dependencies 字段，
405		// 由单依赖字段推导后再比较。
406		aDeps := append([]uint64(nil), a.Dependencies...)
407		if len(aDeps) == 0 && a.HasDependency {
408			aDeps = []uint64{a.DependencyID}
409		}
410		if len(aDeps) != len(j.dependencies) {
411			return false
412		}
413		for i := range j.dependencies {
414			if aDeps[i] != j.dependencies[i] {
415				return false
416			}
417		}
418		if len(a.Values) != len(j.values) {
419			return false
420		}
421		for i := range j.values {
422			if a.Values[i] != j.values[i] {
423				return false
424			}
425		}
426		if len(j.effectiveValues) == 0 || len(a.EffectiveValues) != len(j.effectiveValues) {
427			return false
428		}
429		for i := range j.effectiveValues {
430			if j.effectiveValues[i] != a.EffectiveValues[i] {
431				return false
432			}
433		}
434		if a.InputsDigest != inputsDigestHex(j.effectiveValues, j.seed) {
435			return false
436		}
437		if a.ResultDigest != resultDigestHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
438			return false
439		}
440		if a.Log != buildLog(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
441			return false
442		}
443		if a.Checksum != checksumHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares, a.Log, a.ResultDigest) {
444			return false
445		}
446		return true
447	}
448	
449	// archiveResultsValid 按既有计算规则对归档保存的实际输入（effectiveValues，
450	// 已含按顺序追加的上游总和，不再追加）复算总和与平方和，归档中的数值结果
451	// 必须与复算结果完全一致。完整性检查只验证日志、摘要与校验值和所写数字
452	// 自洽，无法识别“数字本身写错但全套字段一致”的记录，因此这里以计算规则
453	// 为准。实际输入按规则会造成 int64 溢出时 ok 为 false，任何数值结果
454	// （包括回绕后的值）都不能作为有效成功结果保留。
455	//
456	// 调用前须已通过 archiveIntact（保证 archive 非空且有效输入非空）。
457	func archiveResultsValid(j *storedJob) bool {
458		a := j.archive
459		sum, sumSquares, _, ok := computeResult(j.effectiveValues, j.seed, nil)
460		if !ok {
461			return false
462		}
463		return a.Sum == sum && a.SumOfSquares == sumSquares
464	}
465	
466	// effectiveInputsCorrespond 校验成功记录中实际参与计算的输入与原始提交
467	// 参数、直接依赖数量之间的对应关系：
468	//   - 原始序列必须非空；
469	//   - 原始序列逐项、按原次序完整出现在实际输入的开头——负数、零与重复
470	//     整数一律按位置判断，不比较总和或平方和，也不忽略次序；
471	//   - 实际输入总长度必须恰好等于原始序列长度加直接依赖数量。无依赖时两份
472	//     序列必须完全相同；有单个或多个依赖时，原始部分之后只能保留每个直接
473	//     上游各占一个位置的追加部分，不能借依赖之名替换、截短原始部分，也不
474	//     能多出未记录的输入。
475	//
476	// 该规则防止把另一份输入的自洽结果挂在原始参数下：例如原始参数为 [2,-3]
477	// 而实际输入被换成 [-3,2] 时，总和与平方和不变，摘要、日志与校验值又只
478	// 绑定实际输入，全套字段仍会自洽，只有按位置比对原始参数并核对追加数量
479	// 才能识别。旧的单依赖记录恢复后依赖列表恰含一个作业号，按同一含义判断。
480	//
481	// 调用前须已通过 archiveIntact（保证 archive 非空、实际输入非空且归档内
482	// 副本与顶层一致）。
483	func effectiveInputsCorrespond(j *storedJob) bool {
484		n := len(j.values)
485		if n == 0 {
486			return false
487		}
488		if len(j.effectiveValues) != n+len(j.dependencies) {
489			return false
490		}
491		for i := 0; i < n; i++ {
492			if j.effectiveValues[i] != j.values[i] {
493				return false
494			}
495		}
496		return true
497	}
498

